    let text = "%%start\n*i32(*i32) choose = fn(input) { if (input == null) { input } else { null } };\nunit() outer = fn { i32 owner = 2; *i32 checked = choose(&owner); *i32() inner = fn() { checked }; inner; };\n%%end";
